{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "After oral administration, Rg1 and other ginsenosides were detected in brain tissue, indicating they cross the blood-brain barrier despite brain concentrations being 8–15 times lower than plasma.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ginsenoside Rh3 was detected in rat hippocampus at 520 ng/g after oral administration, demonstrating meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In a rat cerebral ischemic model, Rg1 brain concentration was 14.59 ng/mL at 60 min and was labeled poor penetration, suggesting limited brain distribution in that disrupted-barrier setting.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: direct in-vivo evidence shows Rg1 and related ginsenosides are detected in brain after systemic administration, including Rg1 after oral dosing. One poor-penetration label in an ischemic model is outweighed by multiple positive CNS-access observations.",
  "evidence_gaps": [
    "C04 was generated in a cerebral ischemic model, where BBB integrity may be altered, limiting normal-state transferability.",
    "Most positive records are qualitative or single-time-point; quantitative unbound brain-to-plasma ratios are lacking.",
    "Several supporting records are for structurally related saponins rather than the exact query, so extrapolation relies on class-level behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

